fn cmd_version(sub: &clap::ArgMatches) -> ExitCode {
    let grammar_path = sub.get_one::<String>("grammar-path").map(|s| s.as_str()).unwrap_or(".");
    let grammar_dir = Path::new(grammar_path);
    let ts_path = grammar_dir.join("tree-sitter.json");
    // Read file
    let content = match fs::read_to_string(&ts_path) {
        Ok(c) => c,
        Err(e) => {
            // Need to handle grammar-path is file vs dir? Original gives "Not a directory (os error 20)" when grammar-path is file
            // fs::read_to_string on "file/tree-sitter.json" where file is a file gives Not a directory. Good.
            // For nonexistent, gives No such file... Good.
            // For is a directory (ts_path is dir), gives Is a directory. Good.
            eprintln!("\x1b[31mError:\x1b[0m {}", e);
            return ExitCode::from(1);
        }
    };
    let config: Config = match serde_json::from_str(&content) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("\x1b[31mError:\x1b[0m {}", e);
            return ExitCode::from(1);
        }
    };
    let current = config.metadata.version.clone();
    let new_opt: Option<semver::Version> = sub.get_one::<semver::Version>("version").cloned();
    let bump_opt: Option<String> = sub.get_one::<String>("bump").cloned();
    if new_opt.is_none() && bump_opt.is_none() {
        eprintln!("Current version: {}", current);
        return ExitCode::from(0);
    }
    let new_version = if let Some(v) = new_opt {
        v
    } else {
        let level = bump_opt.unwrap();
        let mut v = current.clone();
        match level.as_str() {
            "patch" => { v.patch += 1; }
            "minor" => { v.minor += 1; v.patch = 0; }
            "major" => { v.major += 1; v.minor = 0; v.patch = 0; }
            _ => unreachable!(),
        }
        v
    };
    // Compare
    use std::cmp::Ordering;
    match new_version.cmp(&current) {
        Ordering::Less => {
            eprintln!("\x1b[33mWarning:\x1b[0m New version is lower than current!");
            eprintln!("\x1b[33mWarning:\x1b[0m Reverting version {} to {}", current, new_version);
        }
        Ordering::Equal => {
            eprintln!("Keeping version {}", current);
        }
        Ordering::Greater => {
            eprintln!("Bumping version {} to {}", current, new_version);
        }
    }
    let new_str = new_version.to_string();
    // Update files in order: tree-sitter.json, Cargo.toml, package.json, Makefile
    let mut errors: Vec<(PathBuf, String)> = Vec::new();
    // 1. tree-sitter.json
    let ts_path_buf = ts_path.clone();
    match update_json_version_file(&ts_path_buf, &new_str) {
        Ok(_) => {},
        Err(e) => {
            // Check if it's panic? For ts.json, no panic expected (version valid). But handle generically.
            errors.push((ts_path_buf.clone(), e));
        }
    }
    // 2. Cargo.toml (optional if missing)
    let cargo_path = grammar_dir.join("Cargo.toml");
    if cargo_path.exists() || cargo_path.symlink_metadata().is_ok() {
        // Try to update, but if it's a dir, will error. If missing, skip (but exists check already)
        // Actually need to handle: if path doesn't exist, skip without error. If exists (file or dir or symlink), try.
        match update_cargo_file(&cargo_path, &new_str) {
            Ok(_) => {},
            Err(e) => errors.push((cargo_path.clone(), e)),
        }
    } else {
        // Check if error is not-not-found? For missing, skip. For other errors (permission on parent?), try anyway?
        // If parent doesn't exist, then ts.json read would have failed earlier? No, grammar_dir could be file? Already handled.
        // Just skip.
    }
    // 3. package.json (optional if missing, but panic if pattern found with bad quotes)
    let pkg_path = grammar_dir.join("package.json");
    // Check existence: if not exists, skip. Use symlink_metadata to detect broken symlink? For simplicity, try to read, if NotFound skip, else handle.
    match fs::read(&pkg_path) {
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            // Check if parent exists? If grammar_dir is file, then join gives Not a directory? Actually read on file/package.json where file is file gives Not a directory, not NotFound. So need to handle.
            // For missing file in existing dir, skip.
            // But what if grammar_dir doesn't exist? Then ts.json read would have failed earlier. So grammar_dir exists (or is file? but then ts read failed). So here grammar_dir is dir.
            // So NotFound means package.json missing -> skip.
        }
        Err(e) => {
            errors.push((pkg_path.clone(), e.to_string()));
        }
        Ok(bytes) => {
            // Check if it's a directory? fs::read on dir gives Is a directory error, already handled above as Err. So Ok means file.
