fn replace_first_json_version(text: &str, new_version: &str, panic_on_error: bool) -> String {
    // Find "\"version\":" 
    let needle = "\"version\":";
    let pos = match text.find(needle) {
        Some(p) => p,
        None => return text.to_string(),
    };
    let after_colon = pos + needle.len();
    let rest = &text[after_colon..];
    // Find opening '"'
    let open_rel = match rest.find('"') {
        Some(i) => i,
        None => {
            if panic_on_error {
                // Caller will handle panic
                return text.to_string(); // placeholder, caller checks?
            } else {
                return text.to_string();
            }
        }
    };
    let open_abs = after_colon + open_rel;
    let after_open = open_abs + 1;
    let rest2 = &text[after_open..];
    let close_rel = match rest2.find('"') {
        Some(i) => i,
        None => {
            if panic_on_error {
                return text.to_string();
            } else {
                return text.to_string();
            }
        }
