            fs::write(path, to_write).map_err(|e| PackageError::FileError(e.to_string()))?;
            return Ok(());
        }
    };
    let after_colon = pos + needle.len();
    let rest = &text[after_colon..];
    let open_rel = match rest.find('"') {
        Some(i) => i,
        None => return Err(PackageError::Panic("crates/cli/src/version.rs:247:60".to_string())),
    };
    let open_abs = after_colon + open_rel;
    let after_open = open_abs + 1;
    let rest2 = &text[after_open..];
    let close_rel = match rest2.find('"') {
        Some(i) => i,
        None => return Err(PackageError::Panic("crates/cli/src/version.rs:249:63".to_string())),
    };
    let close_abs = after_open + close_rel;
    let content = &text[after_open..close_abs];
    if content.is_empty() {
        return Err(PackageError::Panic("crates/cli/src/version.rs:249:63".to_string()));
    }
    let mut out = String::with_capacity(text.len() - content.len() + new_version.len());
