fn update_makefile(path: &Path, new_version: &str) -> Result<(), String> {
    let bytes = fs::read(path).map_err(|e| e.to_string())?;
    let text = String::from_utf8(bytes).map_err(|_| "stream did not contain valid UTF-8".to_string())?;
    let normalized = text.replace("\r\n", "\n").replace('\r', "\n");
    if normalized.is_empty() {
        fs::write(path, "\n").map_err(|e| e.to_string())?;
        return Ok(());
    }
    let mut lines: Vec<String> = Vec::new();
    for line in normalized.lines() {
        if line.starts_with("VERSION") {
            lines.push(format!("VERSION := {}", new_version));
        } else {
            lines.push(line.to_string());
        }
    }
    if lines.is_empty() {
        fs::write(path, "\n").map_err(|e| e.to_string())?;
        return Ok(());
    }
    let mut out = lines.join("\n");
    out.push('\n');
    fs::write(path, out).map_err(|e| e.to_string())?;
    Ok(())
