fn cmd_dump_languages(sub: &clap::ArgMatches) -> ExitCode {
    let config_path_opt = sub.get_one::<String>("config-path").map(|s| s.as_str());
    let config_path: PathBuf = if let Some(p) = config_path_opt {
        PathBuf::from(p)
    } else {
        match config_path_default() {
            Some(p) => p,
            None => {
                eprintln!("\x1b[33mWarning:\x1b[0m You have not configured any parser directories!");
                eprintln!("Please run `tree-sitter init-config` and edit the resulting");
                eprintln!("configuration file to indicate where we should look for");
                eprintln!("language grammars.");
                eprintln!();
                return ExitCode::from(0);
            }
        }
    };
    // If using default path and file doesn't exist, warn and return 0 (as observed for no config file)
    // If using --config-path and file doesn't exist, error with path in message
    let content = match fs::read_to_string(&config_path) {
        Ok(c) => c,
        Err(e) => {
            if config_path_opt.is_some() {
                // Explicit path: error with path
                eprintln!("\x1b[31mError:\x1b[0m {} ({})", e, config_path.display());
                return ExitCode::from(1);
            } else {
                // Default path missing: warn about parser directories (as observed)
                // Check if error is NotFound? For other errors (Is a directory, etc.), what to do? Likely same warning? Or error?
                // For now, if default path missing, warn. For other errors, error?
                // Test: what if default config path is a directory? Need to handle, but for now warn for NotFound, error otherwise?
                if e.kind() == std::io::ErrorKind::NotFound {
                    eprintln!("\x1b[33mWarning:\x1b[0m You have not configured any parser directories!");
                    eprintln!("Please run `tree-sitter init-config` and edit the resulting");
                    eprintln!("configuration file to indicate where we should look for");
                    eprintln!("language grammars.");
                    eprintln!();
                    return ExitCode::from(0);
                } else {
                    eprintln!("\x1b[31mError:\x1b[0m {}", e);
                    return ExitCode::from(1);
                }
            }
        }
    };
    // Parse config JSON: expects {"parser-directories": [...], ...}
    // If parser-directories missing or empty, warn.
    // If JSON invalid, error "Bad JSON config <path> -- <serde error>"
    #[derive(Deserialize)]
    struct ConfigFile {
        #[serde(rename = "parser-directories")]
        parser_directories: Option<Vec<String>>,
    }
    let cfg: ConfigFile = match serde_json::from_str(&content) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("\x1b[31mError:\x1b[0m Bad JSON config {} -- {}", config_path.display(), e);
            return ExitCode::from(1);
        }
    };
    let dirs = match cfg.parser_directories {
        Some(d) if !d.is_empty() => d,
        _ => {
            eprintln!("\x1b[33mWarning:\x1b[0m You have not configured any parser directories!");
            eprintln!("Please run `tree-sitter init-config` and edit the resulting");
            eprintln!("configuration file to indicate where we should look for");
            eprintln!("language grammars.");
            eprintln!();
            return ExitCode::from(0);
        }
    };
    // For each parser dir, list subdirs starting with tree-sitter-? Or all subdirs?
    // Observed: dirname "foo" (not tree-sitter-*) gave no output (ignored). "tree-sitter-foo" and "tree-sitter-bar" gave output.
    // So only dirs starting with "tree-sitter-"? Or maybe all dirs that contain tree-sitter.json? Let's assume only tree-sitter-*.
    // Actually, need to test: what if dir is "tree-sitter-foo" but no tree-sitter.json? Probably ignored (no warning?).
