        };
        let mut subdirs: Vec<PathBuf> = Vec::new();
        for entry in entries {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            let path = entry.path();
            // Check if dir and name starts with tree-sitter-? Or just dir?
            // Let's check file_type: must be dir (or symlink to dir?).
