            if !ft.is_dir() {
                continue;
            }
            if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                if !name.starts_with("tree-sitter-") {
                    continue;
                }
            } else {
                continue;
            }
            subdirs.push(path);
        }
        subdirs.sort();
        for sub in subdirs {
            let ts_path = sub.join("tree-sitter.json");
            let content = match fs::read_to_string(&ts_path) {
