                // Observed: None for missing, Some(["queries/highlights.scm"]) for string "queries/highlights.scm".
                // What for array? Probably Some(["a","b"]).
                match grammar.highlights {
                    None => eprintln!("highlights: None"),
                    Some(PathsJSON::Single(s)) => eprintln!("highlights: Some([{:?}])", s),
                    Some(PathsJSON::Multiple(v)) => {
                        let inner: Vec<String> = v.iter().map(|s| format!("{:?}", s)).collect();
                        eprintln!("highlights: Some([{}])", inner.join(", "));
                    }
                }
                // file_types: Option<Vec<String>> -> ["foo"] or []? What if None? Probably []? Need to test.
                match grammar.file_types {
                    None => eprintln!("file_types: []"),
                    Some(v) => {
                        let inner: Vec<String> = v.iter().map(|s| format!("{:?}", s)).collect();
                        eprintln!("file_types: [{}]", inner.join(", "));
                    }
                }
                // content_regex, injection_regex: Option<String> -> None or Some(Regex("..."))
