fn check_executable_in_path(name: &str) -> bool {
    if name.contains('/') {
        return false;
    }
    if let Some(paths) = env::var_os("PATH") {
        for dir in env::split_paths(&paths) {
            let p = dir.join(name);
            if let Ok(md) = fs::metadata(&p) {
                if md.is_file() {
                    // Check executable bit? On Unix, check mode & 0o111
                    #[cfg(unix)]
                    {
                        use std::os::unix::fs::PermissionsExt;
                        if md.permissions().mode() & 0o111 != 0 {
                            return true;
                        }
                    }
                    #[cfg(not(unix))]
                    {
                        return true;
                    }
                }
            }
        }
    }
    false
}

