// Returns Ok(parser_dirs) on success (dirs may be empty, warning already printed if needed),
// Err(exit_code) if should exit immediately (error already printed).
fn load_config_for_command(sub: &clap::ArgMatches, warn_on_empty: bool) -> Result<Vec<String>, ExitCode> {
    let explicit = sub.get_one::<String>("config-path").map(|s| s.as_str());
    if let Some(p) = explicit {
        let path = Path::new(p);
        let content = match fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("\\x1b[31mError:\\x1b[0m {} ({})", e, path.display());
                return Err(ExitCode::from(1));
            }
        };
        #[derive(Deserialize)]
        struct Cfg {
            #[serde(rename = "parser-directories")]
            parser_directories: Option<Vec<String>>,
        }
        let cfg: Cfg = match serde_json::from_str(&content) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("\\x1b[31mError:\\x1b[0m Bad JSON config {} -- {}", path.display(), e);
                return Err(ExitCode::from(1));
            }
        };
        match cfg.parser_directories {
            Some(d) if !d.is_empty() => Ok(d),
            _ => {
                if warn_on_empty {
                    print_no_parser_dirs_warning();
                }
                Ok(Vec::new())
            }
        }
    } else {
        let def_path = match config_path_default() {
            Some(p) => p,
